<div class="page-heading"><div><p class="eyebrow">Security</p><h1>Audit log</h1><p>Review sign-ins and important data changes.</p></div></div><form class="filter-bar" method="get"><input name="q" value="<?=e($q)?>" placeholder="User, entity, or record ID"><input name="action" value="<?=e($action)?>" placeholder="Action contains"><button class="button">Filter</button></form><section class="card table-card"><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Record</th><th>IP address</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['display_name']?:'System/unknown')?></td><td><strong><?=e($log['action'])?></strong></td><td><?=e(trim(($log['entity_type']??'').' #'.($log['entity_id']??''),' #'))?></td><td><?=e($log['ip_address'])?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="5" class="empty">No audit entries found.</td></tr><?php endif;?></tbody></table></section>
